import React, { createContext, useState, useContext, useEffect } from 'react';
import axios from 'axios';

// Создаем контекст аутентификации
const AuthContext = createContext();

// URL API
const API_URL = 'http://localhost:5000/api';

export const useAuth = () => {
  return useContext(AuthContext);
};

export const AuthProvider = ({ children }) => {
  const [user, setUser] = useState(null);
  const [isAuthenticated, setIsAuthenticated] = useState(false);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState(null);

  // Проверка токена и загрузка данных пользователя при запуске
  useEffect(() => {
    const checkAuth = async () => {
      const token = localStorage.getItem('token');
      
      if (!token) {
        setLoading(false);
        return;
      }

      try {
        // Устанавливаем токен для всех запросов
        axios.defaults.headers.common['Authorization'] = `Bearer ${token}`;
        
        // Получаем данные пользователя
        const response = await axios.get('/api/auth/me');
        
        setUser(response.data);
        setIsAuthenticated(true);
      } catch (err) {
        console.error('Ошибка аутентификации:', err);
        // Удаляем некорректный токен
        localStorage.removeItem('token');
        delete axios.defaults.headers.common['Authorization'];
      } finally {
        setLoading(false);
      }
    };

    checkAuth();
  }, []);

  // Функция для входа в систему
  const login = async (username, password) => {
    setLoading(true);
    setError(null);
    
    try {
      const response = await axios.post('/api/auth/login', { username, password });
      const { token, user: userData } = response.data;
      
      // Сохраняем токен
      localStorage.setItem('token', token);
      
      // Устанавливаем токен для всех запросов
      axios.defaults.headers.common['Authorization'] = `Bearer ${token}`;
      
      setUser(userData);
      setIsAuthenticated(true);
      
      return { success: true };
    } catch (err) {
      let errorMessage = 'Произошла ошибка при входе';
      
      if (err.response) {
        errorMessage = err.response.data.message || errorMessage;
      }
      
      setError(errorMessage);
      return { success: false, error: errorMessage };
    } finally {
      setLoading(false);
    }
  };

  // Функция для выхода из системы
  const logout = () => {
    localStorage.removeItem('token');
    delete axios.defaults.headers.common['Authorization'];
    setUser(null);
    setIsAuthenticated(false);
  };

  // Функция для регистрации
  const register = async (userData) => {
    setLoading(true);
    setError(null);
    
    try {
      const response = await axios.post('/api/auth/register', userData);
      
      return { success: true, data: response.data };
    } catch (err) {
      let errorMessage = 'Произошла ошибка при регистрации';
      
      if (err.response) {
        errorMessage = err.response.data.message || errorMessage;
      }
      
      setError(errorMessage);
      return { success: false, error: errorMessage };
    } finally {
      setLoading(false);
    }
  };

  const isAdmin = () => {
    return user?.role === 'admin';
  };

  const isDispatcher = () => {
    return user?.role === 'dispatcher';
  };

  const isWorkshopManager = () => {
    return user?.role === 'workshop_manager';
  };

  // Значение, которое будет доступно через контекст
  const value = {
    user,
    isAuthenticated,
    loading,
    error,
    login,
    logout,
    register,
    isAdmin,
    isDispatcher,
    isWorkshopManager
  };

  return (
    <AuthContext.Provider value={value}>
      {children}
    </AuthContext.Provider>
  );
};

export default AuthContext;
